# background ==================================================================

# Here we extract orthologs from emapper output.

# Steps:
# - bf to mm orthologs
#   - get bf to mm orthologs from the bf emapper output (at protein level)
#   - add bf and mm gene ids to this table
#   - only keep the gene id columns and get rid of protein id columns as well as
#     orth_type information (this was likely generated by emapper at the
#     protein level; we will recreate this at the gene level)
#   - keep distinct rows
# - based on the gene_ids, recreate orth_types

# setup =======================================================================
library(tidyverse)
library(here)

bfdir <- here("species/bflo/VNyyK/")
mmdir <- here("species/mmus/genome/GRCm39/106")

# data ========================================================================
bf <- read_tsv(
  here(bfdir, "results/emapper/out/out.emapper.orthologs"),
  comment = "##"
) %>%
  rename(query = `#query`)

bf_genes <- read_tsv(here(bfdir, "results/genes/gid-pid_mapping.tsv"))
mm_genes <- read_csv(here(mmdir, "results/genes/gid-pid-mapping.csv"))

# make column ids consistent for joining
bf_genes <- bf_genes %>%
  rename_with(function(x) paste0("bf_", x))
mm_genes <- mm_genes %>%
  rename(symbol = gene_symbol) %>%
  rename_with(function(x) paste0("mm_", x))

# remove gid and pid version numbers for mouse
mm_genes <- mm_genes %>%
  mutate(
    mm_gene_id = str_remove(mm_gene_id, "\\.\\d+"),
    mm_protein_id = str_remove(mm_protein_id, "\\.\\d+")
  )

# bflo to mmus orthologs ======================================================
bf <- bf %>%
  filter(species == "Mus musculus(10090)") %>%
  # 1 ortholog per row
  mutate(orthologs = str_split(orthologs, ",")) %>%
  unnest(orthologs) %>%
  # clean up
  mutate(orthologs = str_remove(orthologs, "^\\*"))

# add gene ids and remove other columns
bf_to_mm <- bf %>%
  rename(bf_protein_id = query, mm_protein_id = orthologs) %>%
  left_join(
    select(bf_genes, bf_gene_id, bf_protein_id),
    by = "bf_protein_id"
  ) %>%
  filter(!is.na(bf_gene_id)) %>%
  left_join(
    select(mm_genes, mm_gene_id, mm_protein_id),
    by = "mm_protein_id"
  ) %>%
  filter(!is.na(mm_gene_id)) %>%
  select(bf_gene_id, mm_gene_id) %>%
  distinct()

# assign orthology types ======================================================
orth <- bf_to_mm %>%
  nest(.by = bf_gene_id) %>%
  mutate(n_mmus = map_int(data, ~ length(unique(.x$mm_gene_id)))) %>%
  mutate(
    bf_orth_type = case_when(
      n_mmus == 1 ~ "one2one",
      n_mmus > 1 ~ "one2many"
    )
  ) %>%
  unnest(data) %>%
  nest(.by = mm_gene_id) %>%
  mutate(n_bflo = map_int(data, ~ length(unique(.x$bf_gene_id)))) %>%
  mutate(
    mm_orth_type = case_when(
      n_bflo == 1 ~ "one2one",
      n_bflo > 1 ~ "one2many"
    )
  ) %>%
  unnest(data) %>%
  mutate(
    orth_type = case_when(
      bf_orth_type == "one2many" & mm_orth_type == "one2many" ~ "many2many",
      bf_orth_type == "one2many" & mm_orth_type == "one2one" ~ "one2many",
      bf_orth_type == "one2one" & mm_orth_type == "one2many" ~ "many2one",
      bf_orth_type == "one2one" & mm_orth_type == "one2one" ~ "one2one"
    )
  ) %>%
  select(bf_gene_id, mm_gene_id, orth_type)

# add mouse symbols ===========================================================

orth <- left_join(
  orth,
  (mm_genes %>%
    select(mm_gene_id, mm_symbol) %>%
    distinct()),
  by = "mm_gene_id"
)

# write results ===============================================================
write_csv(
  orth,
  here(bfdir, "results/emapper/processed/emapper_orthologs_mouse.csv")
)

# end =========================================================================
